<div class="page-heading"><div><h1>Mould readiness</h1><p>Moulds made and waiting for metal, by iron grade. Use it to decide when to light the cupola or run the induction furnace.</p></div></div>
<div class="panel"><div class="table-wrap"><table><thead><tr><th>Grade</th><th>Orders</th><th>Accepted, not assembled</th><th>Assembled, ready to pour</th><th>Castings</th><th>Metal needed kg</th><?php $__currentLoopData = $furnaces; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $f): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><th><?php echo e($f->code); ?> heats<div class="muted small"><?php echo e(rtrim(rtrim($f->rated_capacity_kg,'0'),'.')); ?> kg</div></th><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><th>Oldest mould</th></tr></thead><tbody>
<?php $__empty_1 = true; $__currentLoopData = $groups; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $g): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><?php $age = $g['oldest'] ? $g['oldest']->diffInHours(now()) : null; ?>
<tr><td><strong><?php echo e($g['label']); ?></strong></td><td class="small"><?php echo e(implode(', ', array_keys($g['orders']))); ?></td><td><?php echo e($g['unassembled']); ?></td><td><?php echo e($g['ready']); ?></td><td><?php echo e($g['castings']); ?></td><td><?php echo e(number_format($g['metal_kg'], 0)); ?></td>
<?php $__currentLoopData = $furnaces; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $f): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><td><?php echo e($g['metal_kg'] > 0 ? ceil($g['metal_kg'] / (float) $f->rated_capacity_kg) : '—'); ?></td><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?>
<td><?php if($age !== null): ?><span class="<?php echo e($age > $staleHours ? 'status status-cancelled' : ''); ?>"><?php echo e($age); ?> h</span><?php if($age > $staleHours): ?> <span class="small">pour soon: sand is ageing</span><?php endif; ?> <?php else: ?> — <?php endif; ?></td></tr>
